(1262734, 160230, 32997, '<td valign="top">Your subject is adorable, but more importantly the softness to your shot works wonderfully-I love the somewhat shallow depth in the focus, and rich colours.</td>', 'Your subject is adorable, but more importantly the softness to your shot works wonderfully-I love the somewhat shallow depth in the focus, and rich colours.', '2005-03-31 23:00:26.000000', NULL, 1),
(1262737, 161263, 34838, '<td valign="top">Which came first?</td>', 'Which came first?', '2005-03-31 23:02:34.000000', NULL, 1),
