INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1265857, 160858, 31541, '<td valign="top">This is a very pretty picture.  I think that cropping out the right side trees (or moving slightly to the left to remove the trees) would have a little more impact.</td>', 'This is a very pretty picture.  I think that cropping out the right side trees (or moving slightly to the left to remove the trees) would have a little more impact.', '2005-04-02 11:43:56.000000', NULL, 1),
(1265861, 161062, 31541, '<td valign="top">This picture seems pretty good, but it''s a little too small to look at any detail.</td>', 'This picture seems pretty good, but it''s a little too small to look at any detail.', '2005-04-02 11:44:51.000000', NULL, 1),
(1265866, 161182, 31541, '<td valign="top">The detail on the buds (?) is great, but the background on the top left is a bit distracting because it''s the same color as the buds.</td>', 'The detail on the buds (?) is great, but the background on the top left is a bit distracting because it''s the same color as the buds.', '2005-04-02 11:47:09.000000', NULL, 1),
(1265871, 161018, 31541, '<td valign="top">That is a great idea!  Came out perfect!</td>', 'That is a great idea!  Came out perfect!', '2005-04-02 11:48:41.000000', NULL, 1),
(1265884, 161316, 34396, '<td valign="top">Another interesting take on the challenge.  With better focus, I would have scored it higher.</td>', 'Another interesting take on the challenge.  With better focus, I would have scored it higher.', '2005-04-02 11:53:10.000000', NULL, 1),
(1265892, 161082, 11895, '<td valign="top">the balance between that which is in focus and that which is not is off in this shot; because of the title I perceive the theme here to be the progression from bud to blossom, therefore the background flower should also be in focus as it is also a major part of the image; very pleasing colors, and the focus is sharp where you have choosen to put it; maybe just a little more contrast</td>', 'the balance between that which is in focus and that which is not is off in this shot; because of the title I perceive the theme here to be the progression from bud to blossom, therefore the background flower should also be in focus as it is also a major part of the image; very pleasing colors, and the focus is sharp where you have choosen to put it; maybe just a little more contrast', '2005-04-02 11:58:36.000000', NULL, 1),
(1265908, 160943, 35472, '<td valign="top">Great photo! Really interesting composition, beautiful colors, but not very related to challenge. but still 6<br/></td>', 'Great photo! Really interesting composition, beautiful colors, but not very related to challenge. but still 6', '2005-04-02 12:11:13.000000', NULL, 1),
(1265933, 160774, 13305, '<td valign="top">Nicely composed and an excellent subject.  The only problem I see is a slight tilt that could be corrected in cropping.</td>', 'Nicely composed and an excellent subject.  The only problem I see is a slight tilt that could be corrected in cropping.', '2005-04-02 12:24:13.000000', NULL, 1),
(1265939, 161308, 13305, '<td valign="top">I think you got a really nice subject here, but the picture is so dark, it''s hard to tell.  Tweak your levels a bit.</td>', 'I think you got a really nice subject here, but the picture is so dark, it''s hard to tell.  Tweak your levels a bit.', '2005-04-02 12:29:16.000000', NULL, 1),
(1265943, 161028, 13305, '<td valign="top">Excellent composition and take on the challenge.  The sprout is just far enough off center to really catch your eye and make the picture pleasing.  Keep up the good work!</td>', 'Excellent composition and take on the challenge.  The sprout is just far enough off center to really catch your eye and make the picture pleasing.  Keep up the good work!', '2005-04-02 12:31:28.000000', NULL, 1),
(1265948, 160836, 13305, '<td valign="top">Interesting picture, and definitely on target for the challenge.  Good composition, but it''s almost too busy to focus on any one thing.</td>', 'Interesting picture, and definitely on target for the challenge.  Good composition, but it''s almost too busy to focus on any one thing.', '2005-04-02 12:33:31.000000', NULL, 1),
(1265951, 161174, 34396, '<td valign="top">Very clever!</td>', 'Very clever!', '2005-04-02 12:35:16.000000', NULL, 1),
